import tempfile
import time
import unittest
from unittest.mock import MagicMock

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))
PYTHON_DIR = os.path.join(ROOT, "python")
TESTS_DIR = os.path.dirname(os.path.abspath(__file__))
for path in (PYTHON_DIR, TESTS_DIR):
    if path not in sys.path:
        sys.path.insert(0, path)

import ime_smoke_runner  # noqa: E402 - located after ROOT is known
ime_smoke_runner.install_windows_shims()


@unittest.skipIf(ime_smoke_runner.under_wine(),
                 "Wine lacks propsys.dll.VariantToString, which importing cinbase reaches")
@unittest.skipUnless(ime_smoke_runner.opencc_available(),
                     "libopencc.so not installed (Debian: apt install libopencc-dev)")
class CinbaseWildcardTests(unittest.TestCase):
    def setUp(self):
        self.old_appdata = os.environ.get("APPDATA")
        self.old_cwd = os.getcwd()
        self.temp_dir = tempfile.TemporaryDirectory(prefix="pime-cin-wildcard-")
        os.environ["APPDATA"] = self.temp_dir.name
        os.chdir(self.temp_dir.name)

    def tearDown(self):
        os.chdir(self.old_cwd)
        if self.old_appdata is None:
            os.environ.pop("APPDATA", None)
        else:
            os.environ["APPDATA"] = self.old_appdata
        self.temp_dir.cleanup()

    @staticmethod
    def key_event(char_code, key_code=None, printable=False, shift=False):
        event = MagicMock()
        event.charCode = char_code
        event.keyCode = char_code if key_code is None else key_code
        event.seqNum = 1
        event.repeatCount = 1
        event.scanCode = 0
        event.isExtended = False
        event.keyStates = [0] * 256
        event.isPrintableChar.return_value = printable
        event.isKeyDown.side_effect = lambda vk: vk == 0x10 and shift
        event.isKeyToggled.return_value = False
        return event

    def send(self, service, char_code, key_code=None, printable=False, shift=False):
        event = self.key_event(char_code, key_code, printable, shift)
        if service.filterKeyDown(event):
            service.onKeyDown(event)

    def activate_checj(self):
        from input_methods.checj import checj_ime

        service = checj_ime.CheCJTextService(ime_smoke_runner.FakeClient())
        service.onActivate()
        for _ in range(500):
            if checj_ime.CinTable.cin is not None and not checj_ime.CinTable.loading:
                break
            time.sleep(0.02)
        self.assertIsNotNone(checj_ime.CinTable.cin)
        return service

    def use_table(self, service, chardefs, keynames):
        from cinbase.cin import Cin

        payload = json.dumps({
            "chardefs": chardefs,
            "privateuse": {},
            "keynames": keynames,
            "selkey": "1234567890",
            "ename": "test",
            "cname": "test",
        }, ensure_ascii=False)
        service.cin = Cin(io.StringIO(payload), "checj", True)

    def type_wildcard(self, service, letter):
        # Shift+8 is the configured wildcard character `*` for checj.
        self.send(service, ord("*"), 0x38, printable=True, shift=True)
        self.send(service, ord(letter), ord(letter), printable=True)

    def test_pages_use_the_cached_query_and_commit_shows_the_encode(self):
        service = self.activate_checj()
        self.use_table(
            service,
            {"aa": ["\u4e00"], "ba": ["\u3400"], "ca": ["\u4e01"], "da": ["\u4e02"]},
            {"a": "a", "b": "b", "c": "c", "d": "d"},
        )
        service.candPerPage = 2
        service.candPerRow = 2
        service.candidateView.configure(2, 2)

        self.type_wildcard(service, "a")
        self.assertEqual(service.compositionChar, "*a")
        self.assertEqual(service.candidateList, ["\u4e00", "\u4e01"])
        self.assertEqual(service.candidateView.page, 0)
        self.assertTrue(
            service.wildcardQuery.active_for(service.cin, "*a", service.selWildcardChar))

        self.send(service, 0, 0x22)  # VK_NEXT
        self.assertEqual(service.candidateView.page, 1)
        self.assertEqual(service.candidateList, ["\u4e02", "\u3400"])

        # A cache miss would reset the page before the cursor moves; a cache
        # hit keeps both the page and the memoized list.
        self.send(service, 0, 0x27)  # VK_RIGHT
        self.assertEqual((service.candidateView.page, service.candidateCursor), (1, 1))

        self.send(service, ord("2"), ord("2"), printable=True)
        self.assertEqual(service.compositionChar, "")
        self.assertTrue(service.onKeyUpMessage.startswith("\u3400"))
        self.assertTrue(service.showMessageOnKeyUp)
        self.assertFalse(
            service.wildcardQuery.active_for(service.cin, "*a", service.selWildcardChar))

    def test_composition_buffer_space_commit_shows_the_encode(self):
        service = self.activate_checj()
        self.use_table(
            service,
            {"aa": ["\u4e00"], "ba": ["\u3400"], "ca": ["\u4e01"], "da": ["\u4e02"]},
            {"a": "a", "b": "b", "c": "c", "d": "d"},
        )
        service.compositionBufferMode = True
        service.candPerPage = 9
        service.candidateView.configure(9, 3)

        self.type_wildcard(service, "a")
        self.assertTrue(
            service.wildcardQuery.active_for(service.cin, "*a", service.selWildcardChar))

        self.send(service, 0x20, 0x20, printable=True)
        self.assertEqual(service.compositionChar, "")
        self.assertTrue(service.onKeyUpMessage.startswith("\u4e00"))
        self.assertTrue(service.showMessageOnKeyUp)
        self.assertFalse(
            service.wildcardQuery.active_for(service.cin, "*a", service.selWildcardChar))

    def test_homophone_commit_does_not_show_the_wildcard_encode(self):
        service = self.activate_checj()
        self.use_table(
            service,
            {"aa": ["\u4e00"], "ba": ["\u3400"], "ca": ["\u4e01"]},
            {"a": "a", "b": "b", "c": "c"},
        )
        service.candPerPage = 9
        service.candidateView.configure(9, 3)
        self.type_wildcard(service, "a")
        self.assertTrue(
            service.wildcardQuery.active_for(service.cin, "*a", service.selWildcardChar))

        service.homophoneQuery = True
        service.homophonemode = True
        service.homophoneChar = service.compositionChar
        service.homophonecandidates = ["\u4e8c"]
        service.onKeyUpMessage = None
        service.showMessageOnKeyUp = False
        self.send(service, ord("1"), ord("1"), printable=True)

        self.assertEqual(service.compositionChar, "")
        self.assertIsNone(service.onKeyUpMessage)
        self.assertFalse(service.showMessageOnKeyUp)

    def test_common_tier_duplicates_reach_the_candidate_list(self):
        service = self.activate_checj()
        self.use_table(service, {"aa": ["\u4e00"], "ba": ["\u4e00"]}, {"a": "a", "b": "b"})
        service.candPerPage = 9
        service.candidateView.configure(9, 3)

        self.type_wildcard(service, "a")
        self.assertEqual(service.candidateList, ["\u4e00", "\u4e00"])

    def test_empty_result_is_cached_and_keys_do_not_crash(self):
        service = self.activate_checj()
